#include "canard_am13x.h"
#include "canard.h"
#include "ti_sdk_dl_config.h"
#include "device.h"
#include "dl_gpio.h"
#include <string.h>

/* ========================================================================== */
/*                          Internal Constants                                */
/* ========================================================================== */

#define MCAN_TX_BUFFER_INDEX        (0U)
#define MCAN_RX_FIFO0_INDEX         (0U)
#define MCAN_MODE_TIMEOUT_LOOPS     (1000000U)
#define MCAN_TRANSCEIVER_DELAY_MS   (10U)
#define MCAN_MAX_EXT_FILTERS        (8U)

/* ========================================================================== */
/*                          GPIO Macros — SysConfig Generated                */
/* ========================================================================== */

/*
 * GPIO_GRP_0_PORT and GPIO_GRP_0_TCAN_STB_PIN are generated by
 * example.syscfg in the TI Toolchain. They identify the GPIO port and
 * pin connected to the TCAN transceiver STB (standby) input.
 *
 * STB is active-low:
 *   Low  (pin cleared) → transceiver active, CAN bus connected
 *   High (pin set)     → transceiver in standby, CAN bus disconnected
 *
 * To change the STB pin assignment, update the GPIO configuration in
 * example.syscfg and regenerate ti_sdk_dl_config.h.
 */

/* ========================================================================== */
/*                          Module State                                      */
/* ========================================================================== */

static CanardTI_MCAN_Stats gStats;
static bool                gAbortTxOnError = false;
static bool                gInitialized    = false;
static MCAN_Regs*          gMcan           = NULL;
static uint32_t            gLastTxCanardId = 0U;
static bool                gTxPending      = false;

/* ========================================================================== */
/*                          Private: Frame ID Conversion                     */
/* ========================================================================== */

static void convertFrameIdCanardToMcan(uint32_t  canardId,
                                        uint32_t* outId,
                                        uint32_t* outXtd,
                                        uint32_t* outRtr)
{
    if (canardId & CANARD_CAN_FRAME_EFF)
    {
        *outId  = canardId & CANARD_CAN_EXT_ID_MASK;
        *outXtd = 1U;
    }
    else
    {
        *outId  = (canardId & CANARD_CAN_STD_ID_MASK) << 18U;
        *outXtd = 0U;
    }

    *outRtr = (canardId & CANARD_CAN_FRAME_RTR) ? 1U : 0U;
}

/*
 * convertFrameIdMcanToCanard
 *
 * Maps TI MCAN RxBufElement fields back to a libcanard frame->id word.
 * Restores CANARD_CAN_FRAME_EFF for extended frames and
 * CANARD_CAN_FRAME_RTR for remote frames.
 */
static uint32_t convertFrameIdMcanToCanard(uint32_t mcanId,
                                            uint32_t xtd,
                                            uint32_t rtr)
{
    uint32_t canardId = 0U;

    if (xtd)
    {
        canardId = (mcanId & CANARD_CAN_EXT_ID_MASK) | CANARD_CAN_FRAME_EFF;
    }
    else
    {
        canardId = (mcanId >> 18U) & CANARD_CAN_STD_ID_MASK;
    }

    if (rtr)
    {
        canardId |= CANARD_CAN_FRAME_RTR;
    }

    return canardId;
}

/* ========================================================================== */
/*                          Private: Error Processing                        */
/* ========================================================================== */

static void processErrorStatus(void)
{
    if (gMcan == NULL) { return; }

    DL_MCAN_ProtocolStatus ps;
    DL_MCAN_getProtocolStatus(gMcan, &ps);

    if (ps.lastErrCode != 0U)
    {
        gStats.errorCount++;

        if (gAbortTxOnError || ps.busOffStatus)
        {
            DL_MCAN_txBufCancellationReq(gMcan, MCAN_TX_BUFFER_INDEX);
            gTxPending = false;
        }
    }
}

/* ========================================================================== */
/*                          Public: Initialisation                           */
/* ========================================================================== */

int16_t canardTI_MCAN_Init(void*                  mcanInstance,
                            CanardTI_MCAN_IfaceMode ifaceMode)
{
    if (mcanInstance == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    if ((ifaceMode != CanardTI_MCAN_IfaceModeNormal)                  &&
        (ifaceMode != CanardTI_MCAN_IfaceModeSilent)                  &&
        (ifaceMode != CanardTI_MCAN_IfaceModeLoopback)                &&
        (ifaceMode != CanardTI_MCAN_IfaceModeAutomaticTxAbortOnError))
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    /* Reset all module state */
    memset(&gStats, 0, sizeof(gStats));
    gMcan           = (MCAN_Regs*)mcanInstance;
    gAbortTxOnError = (ifaceMode == CanardTI_MCAN_IfaceModeAutomaticTxAbortOnError);
    gTxPending      = false;
    gLastTxCanardId = 0U;
    gInitialized    = false;

    /*
     * Wait for MCAN to reach Normal operating mode.
     * SysConfig (SYSCFG_DL_init) must have already started the peripheral.
     * If this times out, example.syscfg MCAN configuration should be checked.
     * Syscfg is set to accept non matching frames in RX FIFO 0
     */
    uint32_t timeout = MCAN_MODE_TIMEOUT_LOOPS;
    while (DL_MCAN_OPERATION_MODE_NORMAL != DL_MCAN_getOpMode(gMcan))
    {
        if (--timeout == 0U)
        {
            gMcan = NULL;
            return -CANARD_TI_MCAN_ERROR_MODE_NOT_SET;
        }
    }

    /*
     * Release TCAN transceiver from standby by driving STB pin low.
     * GPIO_GRP_0_PORT and GPIO_GRP_0_TCAN_STB_PIN are generated by
     * example.syscfg. STB is active-low: clearing the pin enables the
     * transceiver and connects the node to the CAN bus.
     */
    DL_GPIO_clearPins(GPIO_GRP_0_PORT, GPIO_GRP_0_TCAN_STB_PIN);

    /* Allow transceiver to exit standby before verifying pin state */
    DEVICE_DELAY_MS(MCAN_TRANSCEIVER_DELAY_MS);

    /*
     * Verify STB pin is actually low. If it reads high, the transceiver
     * is not responding — check hardware connections and SysConfig GPIO
     * assignment for GPIO_GRP_0_TCAN_STB_PIN.
     */
    if (DL_GPIO_readPins(GPIO_GRP_0_PORT, GPIO_GRP_0_TCAN_STB_PIN) != 0U)
    {
        gMcan = NULL;
        return -CANARD_TI_MCAN_ERROR_TRANSCEIVER;
    }

    if (ifaceMode == CanardTI_MCAN_IfaceModeLoopback)
    {
        DL_MCAN_lpbkModeEnable(gMcan, DL_MCAN_LPBK_MODE_INTERNAL, true);
    }
    else if (ifaceMode == CanardTI_MCAN_IfaceModeSilent)
    {
        /* External loopback = monitor mode: receives but does not transmit */
        DL_MCAN_lpbkModeEnable(gMcan, DL_MCAN_LPBK_MODE_EXTERNAL, true);
    }

    gInitialized = true;
    return 0;
}

/* ========================================================================== */
/*                          Public: Acceptance Filters                       */
/* ========================================================================== */

int16_t canardTI_MCAN_ConfigureAcceptanceFilters(
    const CanardTI_MCAN_AcceptanceFilterConfig* filterConfigs,
    uint8_t                                     numFilterConfigs)
{
    if (!gInitialized || gMcan == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_NOT_INIT;
    }

    if ((filterConfigs == NULL) && (numFilterConfigs > 0U))
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    if (numFilterConfigs > MCAN_MAX_EXT_FILTERS)
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    /* TI MCAN filters can only be modified in SW_INIT mode */
    DL_MCAN_setOpMode(gMcan, DL_MCAN_OPERATION_MODE_SW_INIT);

    uint32_t timeout = MCAN_MODE_TIMEOUT_LOOPS;
    while (DL_MCAN_OPERATION_MODE_SW_INIT != DL_MCAN_getOpMode(gMcan))
    {
        if (--timeout == 0U)
        {
            DL_MCAN_setOpMode(gMcan, DL_MCAN_OPERATION_MODE_NORMAL);
            return -CANARD_TI_MCAN_ERROR_MODE_NOT_SET;
        }
    }

    /* Programme requested filters */
    for (uint8_t i = 0U; i < numFilterConfigs; i++)
    {
        bool isExt = ((filterConfigs[i].id   & CANARD_CAN_FRAME_EFF) != 0U) ||
                     ((filterConfigs[i].mask & CANARD_CAN_FRAME_EFF) != 0U);

        if (isExt)
        {
            /* Extended frame filter — strip EFF flag, keep 29-bit ID */
            DL_MCAN_ExtMsgIDFilterElement fe;
            memset(&fe, 0, sizeof(fe));
            fe.efid1 = filterConfigs[i].id   & CANARD_CAN_EXT_ID_MASK;
            fe.efid2 = filterConfigs[i].mask & CANARD_CAN_EXT_ID_MASK;
            fe.efec  = 0x1U; /* Store matching frames in RX FIFO 0 */
            fe.eft   = 0x2U; /* Classic bit-mask filter             */
            DL_MCAN_addExtMsgIDFilter(gMcan, i, &fe);
        }
        else
        {
            /* Standard frame filter — 11-bit ID lives in bits [28:18] */
            DL_MCAN_StdMsgIDFilterElement fe;
            memset(&fe, 0, sizeof(fe));
            fe.sfid1 = (filterConfigs[i].id   >> 18U) & 0x7FFU;
            fe.sfid2 = (filterConfigs[i].mask >> 18U) & 0x7FFU;
            fe.sfec  = 0x1U; /* Store matching frames in RX FIFO 0 */
            fe.sft   = 0x2U; /* Classic bit-mask filter             */
            DL_MCAN_addStdMsgIDFilter(gMcan, i, &fe);
        }
    }

    /* Disable any remaining extended filter slots */
    for (uint8_t i = numFilterConfigs; i < MCAN_MAX_EXT_FILTERS; i++)
    {
        DL_MCAN_ExtMsgIDFilterElement fe;
        memset(&fe, 0, sizeof(fe));
        fe.efec = 0x0U; /* Disabled */
        fe.eft  = 0x2U;
        DL_MCAN_addExtMsgIDFilter(gMcan, i, &fe);
    }

    DL_MCAN_setOpMode(gMcan, DL_MCAN_OPERATION_MODE_NORMAL);

    timeout = MCAN_MODE_TIMEOUT_LOOPS;
    while (DL_MCAN_OPERATION_MODE_NORMAL != DL_MCAN_getOpMode(gMcan))
    {
        if (--timeout == 0U)
        {
            return -CANARD_TI_MCAN_ERROR_MODE_NOT_SET;
        }
    }

    return 0;
}

/* ========================================================================== */
/*                          Public: Transmit                                 */
/* ========================================================================== */

int16_t canardTI_MCAN_Transmit(const CanardCANFrame* frame)
{
    if (frame == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    if (!gInitialized || gMcan == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_NOT_INIT;
    }

    if (frame->id & CANARD_CAN_FRAME_ERR)
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    processErrorStatus();

    bool txBufferBusy =
        (DL_MCAN_getTxBufReqPend(gMcan) & (1U << MCAN_TX_BUFFER_INDEX)) != 0U;

    if (txBufferBusy)
    {
        /*
         * TX buffer is occupied. Return 0 so the caller retries on the
         * next cycle. With a single TX buffer, priority preemption is
         * not possible without cancellation support.
         */
        return 0;
    }

    DL_MCAN_TxBufElement txElem;
    memset(&txElem, 0, sizeof(txElem));

    convertFrameIdCanardToMcan(frame->id,
                                &txElem.id,
                                &txElem.xtd,
                                &txElem.rtr);

    txElem.dlc = frame->data_len;
    txElem.fdf = 0U;    /* Classic CAN frame — no CAN FD bit rate switch */
    txElem.brs = 0U;    /* No bit rate switching                          */
    txElem.esi = 0U;
    txElem.efc = 1U;    /* Store TX event in TX event FIFO                */
    txElem.mm  = 0xAAU; /* Message marker — identifies this driver        */

    memcpy(txElem.data, frame->data, frame->data_len);

    DL_MCAN_writeMsgRam(gMcan, DL_MCAN_MEM_TYPE_BUF,
                        MCAN_TX_BUFFER_INDEX, &txElem);

    DL_MCAN_TXBufTransIntrEnable(gMcan, MCAN_TX_BUFFER_INDEX, true);
    DL_MCAN_TXBufAddReq(gMcan, MCAN_TX_BUFFER_INDEX);

    gLastTxCanardId = frame->id;
    gTxPending      = true;

    gStats.txCount++;
    return 1;
}

/* ========================================================================== */
/*                          Public: TX Ready Query                           */
/* ========================================================================== */

bool canardTI_MCAN_IsTxReady(void)
{
    if (!gInitialized || gMcan == NULL)
    {
        return false;
    }

    return (DL_MCAN_getTxBufReqPend(gMcan) &
            (1U << MCAN_TX_BUFFER_INDEX)) == 0U;
}

/* ========================================================================== */
/*                          Public: TX Completion Check                      */
/* ========================================================================== */

bool canardTI_MCAN_IsTxComplete(void)
{
    if (!gInitialized || gMcan == NULL)
    {
        return false;
    }

    bool complete = (DL_MCAN_getTxBufTransmissionStatus(gMcan) &
                     (1U << MCAN_TX_BUFFER_INDEX)) != 0U;

    if (complete)
    {
        gTxPending = false;
    }

    return complete;
}

/* ========================================================================== */
/*                          Public: Receive                                  */
/* ========================================================================== */

int16_t canardTI_MCAN_Receive(CanardCANFrame* outFrame)
{
    if (outFrame == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_INVALID_ARGUMENT;
    }

    if (!gInitialized || gMcan == NULL)
    {
        return -CANARD_TI_MCAN_ERROR_NOT_INIT;
    }

    processErrorStatus();

    /* Poll RX FIFO 0 fill level */
    DL_MCAN_RxFIFOStatus fifoStatus;
    memset(&fifoStatus, 0, sizeof(fifoStatus));
    fifoStatus.num = DL_MCAN_RX_FIFO_NUM_0;
    DL_MCAN_getRxFIFOStatus(gMcan, &fifoStatus);

    if (fifoStatus.fillLvl == 0U)
    {
        return 0; /* FIFO empty */
    }

    if (fifoStatus.fifoFull)
    {
        gStats.rxOverflowCount++;
    }

    DL_MCAN_RxBufElement rxElem;
    memset(&rxElem, 0, sizeof(rxElem));

    DL_MCAN_readMsgRam(gMcan,
                       DL_MCAN_MEM_TYPE_FIFO,
                       MCAN_RX_FIFO0_INDEX,
                       fifoStatus.num,
                       &rxElem);

    DL_MCAN_writeRxFIFOAck(gMcan, DL_MCAN_RX_FIFO_NUM_0, fifoStatus.getIdx);

    outFrame->id      = convertFrameIdMcanToCanard(rxElem.id,
                                                    rxElem.xtd,
                                                    rxElem.rtr);
    outFrame->data_len = (uint8_t)rxElem.dlc;
    outFrame->iface_id = 0U;

    memcpy(outFrame->data, rxElem.data, outFrame->data_len);

    gStats.rxCount++;
    return 1;
}

/* ========================================================================== */
/*                          Public: RX Available Query                       */
/* ========================================================================== */

bool canardTI_MCAN_IsRxAvailable(void)
{
    if (!gInitialized || gMcan == NULL)
    {
        return false;
    }

    DL_MCAN_RxFIFOStatus fifoStatus;
    memset(&fifoStatus, 0, sizeof(fifoStatus));
    fifoStatus.num = DL_MCAN_RX_FIFO_NUM_0;
    DL_MCAN_getRxFIFOStatus(gMcan, &fifoStatus);

    return (fifoStatus.fillLvl > 0U);
}

/* ========================================================================== */
/*                          Public: Statistics                               */
/* ========================================================================== */

CanardTI_MCAN_Stats canardTI_MCAN_GetStats(void)
{
    return gStats;
}

void canardTI_MCAN_ResetStats(void)
{
    memset(&gStats, 0, sizeof(gStats));
}
